package io.github.rivomesh.cdc;

import io.github.rivomesh.api.SourcePosition;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Real target materialization and receipt replay, including native index safety and target rollback. */
public final class ClickHouseMaterializerAcceptance {
    static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    static TableSchema table(String name,boolean keyless){TableSchema t=new TableSchema();t.id=TableSchema.identity("sales","",name);t.database="sales";t.name=name;TableSchema.Column id=new TableSchema.Column();id.name="id";id.type=TableSchema.Type.INT64;id.nullable=false;TableSchema.Column value=new TableSchema.Column();value.name="value";value.type=TableSchema.Type.STRING;t.columns=Arrays.asList(id,value);if(!keyless){t.primaryKey=Collections.singletonList("id");TableSchema.Index primary=new TableSchema.Index();primary.name="PRIMARY";primary.primary=true;primary.unique=true;primary.columns=Collections.singletonList("id");TableSchema.Index composite=new TableSchema.Index();composite.name="ordinary";composite.method="BTREE";composite.columns=Arrays.asList("id","value");TableSchema.Index unique=new TableSchema.Index();unique.name="unique_value";unique.method="GSI";unique.unique=true;unique.columns=Collections.singletonList("value");t.indexes=Arrays.asList(primary,composite,unique);}return t;}
    static List<Cell> row(long id,String value){return Arrays.asList(Cell.value(Long.toString(id)),Cell.value(value));}
    static SourcePosition position(int n){return new SourcePosition(1,"MYSQL","native-source",Collections.singletonMap("gtid","aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa:1-"+n));}
    static Change change(TableSchema t,String id,Change.Operation operation,List<Cell> before,List<Cell> after){Change c=new Change();c.eventId=id;c.tableId=t.id;c.operation=operation;c.before=before;c.after=after;return c;}
    static SourceTransaction transaction(String generation,int sequence,Change... changes){SourceTransaction tx=new SourceTransaction();tx.id="tx-"+sequence;tx.streamGeneration=generation;tx.position=position(sequence);tx.changes=Arrays.asList(changes);return tx;}
    static MessageSink sink(JdbcJournal journal,Journal.Lease lease,ClickHouseMaterializer.Settings settings)throws Exception{return new MessageSink(settings.subscriptionId,settings.mappings,new JdbcPublicationStore(journal,settings.subscriptionId,lease),()->new ClickHouseMaterializer(settings),4*1024*1024);}
    static Journal.SnapshotState snapshot(JdbcJournal journal,Journal.Lease lease,MessageSink sink,TableSchema table,List<List<Cell>> rows)throws Exception{
        Journal.SnapshotState state=journal.beginSnapshot(lease,"source",table,position(1));journal.appendSnapshot(lease,state,0,rows);journal.finishSnapshot(lease,state);sink.prepare(lease.epoch,table);sink.beginSnapshot(lease.epoch,table,state);sink.snapshotPart(lease.epoch,table,state.snapshotId,journal.snapshotParts("source",table.id,state.snapshotId,0,1).get(0));sink.finishSnapshot(lease.epoch,table,state);return state;
    }
    static void phase(Path markers,String phase)throws Exception{Files.write(markers.resolve(phase+".request"),new byte[]{1});long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(180);while(!Files.exists(markers.resolve(phase+".done"))&&System.nanoTime()<end)Thread.sleep(100);require(Files.exists(markers.resolve(phase+".done")),phase+" did not execute");}
    public static void main(String[] args)throws Exception{
        String suffix=UUID.randomUUID().toString().replace("-",""),generation=UUID.randomUUID().toString(),pipeline="native-"+suffix;
        ClickHouseMaterializer.Settings s=new ClickHouseMaterializer.Settings();s.pipelineId=pipeline;s.subscriptionId="clickhouse";s.generation=generation;s.fingerprint=Codec.sha256("native-config");s.metadataDatabase="meta_"+suffix;s.mappings.put("sales","copy_"+suffix);s.http=new ClickHouseHttpClient.Settings();s.http.url="http://clickhouse:8123";s.http.username="rivomesh";s.http.password="ClickHouse@Test123";
        JdbcJournal.Settings local=new JdbcJournal.Settings();local.pipelineId=pipeline;local.driver="org.h2.Driver";local.url="jdbc:h2:file:"+Files.createTempDirectory("clickhouse-journal-").resolve("journal")+";WRITE_DELAY=0";
        ClickHouseMaterializer.Settings old=Codec.decode(Codec.encode(s),ClickHouseMaterializer.Settings.class);old.pipelineId="compat-"+suffix;old.secondaryIndexes=ClickHouseIndexPlan.Mode.NONE;old.metadataDatabase="old_meta_"+suffix;old.mappings.put("sales","old_copy_"+suffix);
        JdbcJournal.Settings oldLocal=new JdbcJournal.Settings();oldLocal.pipelineId=old.pipelineId;oldLocal.driver="org.h2.Driver";oldLocal.url="jdbc:h2:file:"+Files.createTempDirectory("clickhouse-old-profile-").resolve("journal")+";WRITE_DELAY=0";
        TableSchema oldTable=table("items",false);try(JdbcJournal journal=new JdbcJournal(oldLocal);ClickHouseHttpClient c=new ClickHouseHttpClient(old.http)){journal.initialize(old.fingerprint,old.generation,Collections.singletonList(old.subscriptionId));Journal.Lease lease=journal.claim("compat",600000);try(MessageSink target=sink(journal,lease,old)){target.activate(lease.epoch);snapshot(journal,lease,target,oldTable,Collections.singletonList(row(8,"old-layout")));}require(c.query("SELECT count() FROM system.data_skipping_indices WHERE database='"+old.metadataDatabase+"'").path("data").get(0).get(0).asInt()==0,"NONE silently added indexes");try(MessageSink target=sink(journal,lease,old)){target.activate(lease.epoch);target.prepare(lease.epoch,oldTable);}require(c.query("SELECT count() FROM "+ClickHouseMaterializer.q(old.mappings.get("sales"))+".items").path("data").get(0).get(0).asLong()==1,"NONE reopen lost data");}
        TableSchema keyed=table("items",false),duplicates=table("duplicates",true);String name=ClickHouseMaterializer.q(s.mappings.get("sales"));Path markers=Paths.get(System.getenv("RIVOMESH_CLICKHOUSE_RESTART_DIR"));
        try(JdbcJournal journal=new JdbcJournal(local);ClickHouseHttpClient client=new ClickHouseHttpClient(s.http)){
            require(client.query("SELECT count() FROM system.databases WHERE name='"+s.metadataDatabase+"'").path("data").get(0).get(0).asLong()==0,"Fixture namespace is not initially empty");ClickHouseMaterializer.check(s.http);require(client.query("SELECT count() FROM system.databases WHERE name='"+s.metadataDatabase+"'").path("data").get(0).get(0).asLong()==0,"Capability check created a database");
            journal.initialize(s.fingerprint,generation,Collections.singletonList(s.subscriptionId));Journal.Lease lease=journal.claim("owner",600000);
            Journal.SnapshotState duplicateSnapshot;
            try(MessageSink target=sink(journal,lease,s)){
                target.activate(lease.epoch);snapshot(journal,lease,target,keyed,Collections.singletonList(row(1,"{\"large\":18446744073709551615}")));duplicateSnapshot=snapshot(journal,lease,target,duplicates,Arrays.asList(row(7,"\"same\""),row(7,"\"same\"")));
                require(client.query("SELECT count() FROM "+name+".duplicates").path("data").get(0).get(0).asLong()==2,"Snapshot collapsed identical keyless occurrences");
                String physical="rm3_data_"+Codec.sha256("rivomesh:"+Codec.sha256(s.pipelineId+":"+s.subscriptionId+":"+s.generation)+":"+keyed.id);
                require(client.query("SELECT count() FROM system.data_skipping_indices WHERE database=\'"+s.metadataDatabase+"\' AND table=\'"+physical+"\'").path("data").get(0).get(0).asLong()==2,"BTREE/GSI did not create exactly two deduplicated skip indexes");client.execute("SYSTEM STOP MERGES "+ClickHouseMaterializer.q(s.metadataDatabase)+"."+ClickHouseMaterializer.q(physical));
                Change update=change(keyed,"key-update",Change.Operation.UPDATE,row(1,"{\"large\":18446744073709551615}"),row(3,"{\"new\":true}")),deletion=change(duplicates,"remove-one",Change.Operation.DELETE,row(7,"\"same\""),null);deletion.rowId=Codec.sha256(duplicateSnapshot.snapshotId+":0:0");SourceTransaction first=transaction(generation,1,update,deletion);target.apply(lease.epoch,1,first);target.apply(lease.epoch,1,first);
                require(client.query("SELECT id,value FROM "+name+".items").path("data").get(0).get(0).asLong()==3,"PK move failed");require(client.query("SELECT count() FROM "+name+".duplicates").path("data").get(0).get(0).asLong()==1,"Keyless delete did not remove exactly one occurrence");require(target.checkpoint().sequence==1,"Checkpoint did not follow confirmed rows");
                SourceTransaction indexedUpdate=transaction(generation,2,change(keyed,"indexed-update",Change.Operation.UPDATE,row(3,"{\"new\":true}"),row(3,"{\"latest\":true}")));target.apply(lease.epoch,2,indexedUpdate);
                require(client.query("SELECT count() FROM "+name+".items WHERE value=\'{\"new\":true}\' SETTINGS use_skip_indexes_if_final=1,use_skip_indexes_if_final_exact_mode=0").path("data").get(0).get(0).asLong()==0,"Skip indexes resurrected an old version through FINAL");require(client.query("SELECT count() FROM "+name+".items WHERE value=\'{\"latest\":true}\'").path("data").get(0).get(0).asLong()==1,"Indexed update lost its current version");
            }
            phase(markers,"restart");
            try(MessageSink target=sink(journal,lease,s)){
                target.activate(lease.epoch);target.prepare(lease.epoch,keyed);target.prepare(lease.epoch,duplicates);SourceTransaction second=transaction(generation,3,change(keyed,"new-row",Change.Operation.INSERT,null,row(4,"null")));target.apply(lease.epoch,3,second);require(target.checkpoint().sequence==3,"Restart did not advance checkpoint");require(client.query("SELECT count() FROM "+name+".items").path("data").get(0).get(0).asLong()==2,"Restart lost confirmed business rows");
            }
            phase(markers,"restore");require(client.query("SELECT count() FROM "+name+".items").path("data").get(0).get(0).asLong()==1,"Restore was not an older nonempty target");
            try(MessageSink rolledBack=sink(journal,lease,s)){rolledBack.activate(lease.epoch);try{rolledBack.prepare(lease.epoch,keyed);throw new AssertionError("Later receipt accepted an older nonempty target");}catch(IllegalStateException expected){require("CLICKHOUSE_CONFIRMED_HISTORY_MISSING_REBUILD_REQUIRED".equals(expected.getMessage()),"Wrong rollback protection: "+expected.getMessage());}require(rolledBack.checkpoint().sequence==3,"Rollback rewrote the application checkpoint");}
            System.out.println("CLICKHOUSE_MATERIALIZER_ACCEPTED: auto schema/views, BTREE/GSI skipping indexes, explicit NONE/reopen and FINAL safety, PK move, keyless multiplicity/delete, confirmed checkpoints, duplicate replay, client/server restart and older nonempty target rollback refusal");
        }
    }
}
